type Fn = (...params: any[]) => any;

function memoize(fn: Fn): Fn {
    const root = new Map<any, any>();
    const RESULT = Symbol('result');

    return function(...args: any[]) {
        let curr = root;
        for (const arg of args) {
            if (!curr.has(arg)) {
                curr.set(arg, new Map<any, any>());
            }
            curr = curr.get(arg);
        }
        if (curr.has(RESULT)) {
            return curr.get(RESULT);
        }
        const val = fn(...args);
        curr.set(RESULT, val);
        return val;
    };
}
